class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Set<Long> obstacleSet = new java.util.HashSet<>();
        for (int[] o : obstacles) {
            obstacleSet.add(encode(o[0], o[1]));
        }
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};
        int x = 0, y = 0, dir = 0;
        int maxDist = 0;
        for (int cmd : commands) {
            if (cmd == -2) { dir = (dir + 3) % 4; }
            else if (cmd == -1) { dir = (dir + 1) % 4; }
            else {
                for (int i = 0; i < cmd; i++) {
                    int nx = x + dx[dir], ny = y + dy[dir];
                    if (obstacleSet.contains(encode(nx, ny))) break;
                    x = nx; y = ny;
                    maxDist = Math.max(maxDist, x * x + y * y);
                }
            }
        }
        return maxDist;
    }

    private long encode(int x, int y) {
        return ((long) x + 30001) * 60003 + (y + 30001);
    }
}

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Set<String> obstacleSet = new java.util.HashSet<>();
        for (int[] o : obstacles) obstacleSet.add(o[0] + "," + o[1]);
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};
        int x = 0, y = 0, dir = 0, maxDist = 0;
        for (int cmd : commands) {
            if (cmd == -2) {
                dir = (dir + 3) % 4;
            } else if (cmd == -1) {
                dir = (dir + 1) % 4;
            } else {
                for (int i = 0; i < cmd; i++) {
                    int nx = x + dx[dir], ny = y + dy[dir];
                    if (obstacleSet.contains(nx + "," + ny)) break;
                    x = nx;
                    y = ny;
                    maxDist = Math.max(maxDist, x * x + y * y);
                }
            }
        }
        return maxDist;
    }
}
